# Illustrative swarming model: 6 Developers, 10-working-day Sprint, 6 items of E person-days each.
# Speed-up s(k): assumed (illustrative), k people on one item.
s={1:1.0,2:1.8,3:2.4,6:3.6}
def run(E, k, n_people=6, n_items=6, sprint=10.0):
    swarms=n_people//k
    dur=E/s[k]
    finish=[]
    per=n_items//swarms
    for sw in range(swarms):
        for j in range(1,per+1): finish.append(j*dur)
    finish.sort()
    done=sum(1 for f in finish if f<=sprint+1e-9)
    last=max(finish)
    wip=swarms
    th=n_items/last
    print(f"E={E} k={k}: swarms={swarms} item duration={dur:.2f}d finishes={[round(f,2) for f in finish]} avgCT={dur:.2f} done_by_day10={done} first_done={min(finish):.2f} last={last:.2f} done_by_day5={sum(f<=5+1e-9 for f in finish)} throughput={th:.3f}/day LittleCT={wip/th:.2f} effort_eff={6*E/(n_people*last):.3f}")
for E in [8,10,10.4]:
    for k in [1,2,3]: run(E,k)
print("effective capacity: k=2 ->", 6/2*1.8, "person-day-equivalents/day; k=3 ->", 6/3*2.4)
print("paths", [(n,n*(n-1)//2) for n in [2,3,4,6]])
